-- Lineup Explorer: Valley of the Seven Stars 2026 official set times (posters
-- shared Sep 29, 2026; see lineup-explorer/SEVEN_STARS_2026_SET_TIMES.md).
--
-- The seven-stars-2026 festivals row predates the explorer sync migrations and
-- held a 35-act curated cut with no days. This brings it in line with the
-- page's ACTS array: 89 artists (b2b split), one appearance per artist
-- per festival carrying the night, note and time of that artist's earliest set,
-- the same rule build-set-times.mjs uses for multi-set acts (GRiZ, LSDREAM,
-- Sippy, Mocha, Jaenga, Probcause, Seth David). Thursday 10/8 early-arrival
-- sets use night 'thu'.
--
-- Removes the appearances no longer on the bill (the LSDREAM b2b CloZee
-- "LSZEE" pair, Manic Focus, and Nikita / The Wicked, who are one act,
-- "Nikita, the Wicked"). Checked 2026-09-29: none had member plans or set-time
-- reports. Idempotent.

do $$
begin
  if not exists (select 1 from public.festivals f where f.slug = 'seven-stars-2026' and f.deleted_at is null) then
    raise exception 'seven_stars_2026_set_times: no festivals row with slug seven-stars-2026';
  end if;
end $$;

update public.festivals set timezone = 'America/New_York'
where slug = 'seven-stars-2026' and deleted_at is null and timezone is null;

delete from public.artist_festival_appearances ap
using public.festivals f, public.artists a
where f.slug = 'seven-stars-2026' and f.deleted_at is null
  and ap.festival_id = f.id and ap.artist_id = a.id
  and (a.name_lower in ('manic focus', 'nikita', 'the wicked', 'clozee (lszee)')
       or ap.note like '%LSZEE%');

insert into public.artists (name, genres)
select e->>0, array(select jsonb_array_elements_text(e->1))
from jsonb_array_elements('[["A Hundred Drums",["riddim"]],["A Little Sound",["dubstep"]],["Actual Garbage",["dubstep"]],["Air Castles",["melodic"]],["ALLEYCVT",["riddim"]],["Austeria",["dubstep"]],["Avello",["melodic"]],["Blookah",["dubstep"]],["Capochino",["funk"]],["Casey Club",["dubstep"]],["CloZee",["melodic"]],["Common Creation",["dubstep"]],["Cool Customer",["dubstep"]],["Crankdat",["riddim"]],["Daily Bread",["funk"]],["Distinct Motive",["dubstep"]],["Drew Birch",["funk"]],["Duffrey",["experimental"]],["Effin",["trap"]],["Fabian Mazur",["trap"]],["Flamingosis",["funk"]],["Flozone",["dubstep"]],["Flying Mojito Bros",["funk"]],["Frankly Dope",["funk"]],["G Jones",["experimental"]],["Gallium",["dubstep"]],["Ganja White Night",["dubstep"]],["Gramatik",["funk"]],["GRiZ",["funk"]],["Hedex",["dubstep"]],["HERSHE",["house"]],["Honeycomb",["experimental"]],["Hurtbox",["dubstep"]],["Hydraulix",["dubstep"]],["J Worra",["house"]],["Jack The Giant",["dubstep"]],["Jade Cicada",["melodic"]],["Jaenga",["experimental"]],["Jilli",["melodic"]],["Kaleena Zanders",["house"]],["Know Good",["dubstep"]],["Łaszewo",["melodic"]],["Late Night Radio",["funk"]],["LEVITY",["dubstep"]],["LSDREAM",["melodic"]],["LYNY",["dubstep"]],["Mary Droppinz",["dubstep"]],["MCWAVY",["funk"]],["Mersiv",["dubstep"]],["Mocha",["dubstep"]],["MotifV",["funk"]],["My Friend Jordan",["funk"]],["Never Dull",["house"]],["Nikita, the Wicked",["riddim"]],["Noetika",["melodic"]],["Okayjake",["dubstep"]],["Pauline Herr",["melodic"]],["Player Dave",["funk"]],["Poldoore",["funk"]],["Probcause",["funk"]],["Radiant",["dubstep"]],["Ravenscoon",["experimental"]],["Rhythm City Collective",["funk"]],["Richard Finger",["dubstep"]],["rSUN",["melodic"]],["Seth David",["melodic"]],["Shosh",["house"]],["Sippy",["dubstep"]],["Steller",["dubstep"]],["Sully",["experimental"]],["Super Future",["melodic"]],["The Botanist",["funk"]],["The Glitch Mob",["melodic"]],["The Sponges",["funk"]],["Thought Process",["dubstep"]],["Two Guys",["house"]],["TYNAN",["trap"]],["Vincent Antone",["melodic"]],["Vyhara",["experimental"]],["WHEREAMI",["experimental"]],["Whethan",["melodic"]],["Wonkywilla",["experimental"]],["Wreckno",["dubstep"]],["Xotix",["riddim"]],["YDG",["dubstep"]],["Zen Selekta",["dubstep"]],["Zentik",["experimental"]],["Zingara",["world"]],["Zoska",["dubstep"]]]'::jsonb) e
on conflict (name_lower) do nothing;

create temp table _ss_apps on commit drop as
select a.id as artist_id, f.id as festival_id, (e->>1)::int = 1 as is_headliner, e->>2 as night, e->>3 as note
from jsonb_array_elements('[["a hundred drums",0,"thu",null],["a little sound",0,"sat",null],["actual garbage",0,"thu",null],["air castles",0,"thu",null],["alleycvt",0,"fri",null],["austeria",0,"sat",null],["avello",0,"fri",null],["blookah",0,"sun",null],["capochino",0,"sat",null],["casey club",0,"sat",null],["clozee",1,"sun",null],["common creation",0,"sat",null],["cool customer",0,"sun",null],["crankdat",0,"sat",null],["daily bread",0,"fri","Cloud Conductor set"],["distinct motive",0,"sun",null],["drew birch",0,"fri",null],["duffrey",0,"sat",null],["effin",0,"sat",null],["fabian mazur",0,"sat",null],["flamingosis",0,"fri",null],["flozone",0,"sun",null],["flying mojito bros",0,"sun",null],["frankly dope",0,"sat",null],["g jones",0,"fri",null],["gallium",0,"sat",null],["ganja white night",0,"fri",null],["gramatik",0,"sun","Street Bangerz set"],["griz",1,"fri","Friday closer · 3 sets this weekend"],["hedex",0,"sun",null],["hershe",0,"thu",null],["honeycomb",0,"fri",null],["hurtbox",0,"sat",null],["hydraulix",0,"sat",null],["j worra",0,"sat",null],["jack the giant",0,"thu",null],["jade cicada",1,"fri",null],["jaenga",0,"thu",null],["jilli",0,"sat",null],["kaleena zanders",0,"thu",null],["know good",0,"fri",null],["łaszewo",0,"sun",null],["late night radio",0,"sun",null],["levity",0,"sun","b2b set"],["lsdream",1,"sat",null],["lyny",0,"sun","b2b set"],["mary droppinz",0,"fri",null],["mcwavy",0,"fri",null],["mersiv",0,"sat",null],["mocha",0,"thu",null],["motifv",0,"sun",null],["my friend jordan",0,"sun",null],["never dull",0,"sun",null],["nikita, the wicked",0,"sat",null],["noetika",0,"sat",null],["okayjake",0,"sun",null],["pauline herr",0,"fri",null],["player dave",0,"fri",null],["poldoore",0,"fri",null],["probcause",0,"thu",null],["radiant",0,"thu",null],["ravenscoon",0,"sat",null],["rhythm city collective",0,"thu",null],["richard finger",0,"sat",null],["rsun",0,"fri",null],["seth david",0,"thu",null],["shosh",0,"sat",null],["sippy",0,"thu",null],["steller",0,"sun",null],["sully",0,"fri",null],["super future",0,"fri","live bass"],["the botanist",0,"sun",null],["the glitch mob",1,"sun",null],["the sponges",0,"sun",null],["thought process",0,"fri",null],["two guys",0,"fri",null],["tynan",0,"sat",null],["vincent antone",0,"sun",null],["vyhara",0,"thu",null],["whereami",0,"thu",null],["whethan",0,"sun",null],["wonkywilla",0,"fri",null],["wreckno",0,"sat","Wreckno''s Big Gay Catwalk Competition"],["xotix",0,"sat",null],["ydg",0,"sat",null],["zen selekta",0,"sun",null],["zentik",0,"fri",null],["zingara",0,"sun",null],["zoska",0,"fri",null]]'::jsonb) e
join public.artists a on a.name_lower = e->>0
join public.festivals f on f.slug = 'seven-stars-2026' and f.deleted_at is null;

-- Existing rows (night was NULL): take the page's night / note in place so
-- their ids, and anything hanging off them, are kept.
update public.artist_festival_appearances ap
set night = v.night, note = v.note, is_headliner = v.is_headliner
from _ss_apps v
where ap.artist_id = v.artist_id and ap.festival_id = v.festival_id;

insert into public.artist_festival_appearances (artist_id, festival_id, is_headliner, night, note)
select v.artist_id, v.festival_id, v.is_headliner, v.night, v.note
from _ss_apps v
where not exists (
  select 1 from public.artist_festival_appearances ap
  where ap.artist_id = v.artist_id and ap.festival_id = v.festival_id
);

-- Set times, festival-local wall time -> timestamptz (as build-set-times.mjs emits).
update public.artist_festival_appearances ap set
  start_at = (e->>1)::timestamp at time zone f.timezone,
  end_at = (e->>2)::timestamp at time zone f.timezone,
  stage = e->>3
from jsonb_array_elements('[["a hundred drums","2026-10-08 22:00","2026-10-08 23:00","Barn Burner"],["a little sound","2026-10-10 14:50","2026-10-10 15:50","Big Dipper"],["actual garbage","2026-10-08 19:00","2026-10-08 19:50","Satellite"],["air castles","2026-10-08 21:30","2026-10-08 22:20","Satellite"],["alleycvt","2026-10-09 19:55","2026-10-09 20:55","Big Dipper"],["austeria","2026-10-10 16:00","2026-10-10 17:00","Ouroboros"],["avello","2026-10-09 17:55","2026-10-09 18:55","Big Dipper"],["blookah","2026-10-11 14:50","2026-10-11 15:50","Big Dipper"],["capochino","2026-10-10 15:50","2026-10-10 16:50","Big Dipper"],["casey club","2026-10-10 17:00","2026-10-10 18:00","Zodiac"],["clozee","2026-10-11 18:25","2026-10-11 19:25","Zodiac"],["common creation","2026-10-11 00:00","2026-10-11 01:00","Barn Burner"],["cool customer","2026-10-11 17:50","2026-10-11 18:50","Big Dipper"],["crankdat","2026-10-10 22:45","2026-10-11 00:00","Big Dipper"],["daily bread","2026-10-09 18:30","2026-10-09 19:30","Zodiac"],["distinct motive","2026-10-11 18:50","2026-10-11 19:50","Big Dipper"],["drew birch","2026-10-09 13:00","2026-10-09 14:00","Ouroboros"],["duffrey","2026-10-11 01:00","2026-10-11 02:00","Barn Burner"],["effin","2026-10-10 19:30","2026-10-10 20:30","Big Dipper"],["fabian mazur","2026-10-10 14:00","2026-10-10 15:00","Ouroboros"],["flamingosis","2026-10-09 15:00","2026-10-09 16:00","Ouroboros"],["flozone","2026-10-12 00:00","2026-10-12 01:00","Barn Burner"],["flying mojito bros","2026-10-12 00:00","2026-10-12 01:00","Ouroboros"],["frankly dope","2026-10-10 12:00","2026-10-10 13:00","Ouroboros"],["g jones","2026-10-09 20:30","2026-10-09 21:30","Zodiac"],["gallium","2026-10-10 13:00","2026-10-10 14:00","Ouroboros"],["ganja white night","2026-10-09 21:00","2026-10-09 22:00","Big Dipper"],["gramatik","2026-10-11 17:15","2026-10-11 18:15","Zodiac"],["griz","2026-10-09 22:30","2026-10-10 00:00","Big Dipper"],["hedex","2026-10-11 20:30","2026-10-11 21:30","Zodiac"],["hershe","2026-10-08